    def test_executes_plan_in_order_with_previous_results(self):
        """后续步骤必须拿到已完成的结果，最终只保存用户与最终答案。"""
        agent, llm = self.make_agent([
            '```python\n["计算周二销量", "计算周三销量", "计算总销量"]\n```',
            "30", "25", "70",
        ])
        self.assertEqual(agent.run("计算三天销量"), "70")
        self.assertEqual(llm.invoke.call_count, 4)
        prompts = [call.args[0][-1]["content"] for call in llm.invoke.call_args_list]
        self.assertIn("计算三天销量", prompts[0])
        self.assertIn("# 历史步骤与结果:\n无", prompts[1])
        self.assertIn("步骤 1: 计算周二销量\n结果: 30", prompts[2])
