    def test_custom_prompts_receive_task_plan_history_and_step(self):
        """自定义模板可以使用规划与执行所需的全部占位符。"""
        agent, llm = self.make_agent(
            ['["步骤一", "步骤二"]', "中间结果", "最终结果"],
            custom_prompts={
                "planner": "规划:{question}",
                "executor": "执行:{question}|{plan}|{history}|{current_step}",
            },
        )
        self.assertEqual(agent.run("任务"), "最终结果")
        prompts = [call.args[0][-1]["content"] for call in llm.invoke.call_args_list]
        self.assertEqual(prompts[0], "规划:任务")
        self.assertIn("执行:任务|['步骤一', '步骤二']|无|步骤一", prompts[1])
        self.assertIn("步骤 1: 步骤一\n结果: 中间结果", prompts[2])
        self.assertTrue(prompts[2].endswith("|步骤二"))

    def test_partial_prompt_overrides_are_independent(self):
        """仅覆盖一种模板时保留另一种默认模板，并隔离实例配置。"""
